export const makeT = (lang: Lang): TFn => (en, vars) => {
  const dictionary = DICTIONARIES[lang];
  let s = dictionary?.[en] ?? en;
  if (vars) for (const k of Object.keys(vars)) s = s.split(`{${k}}`).join(String(vars[k]));
  return s;
};

export const localeOf = (lang: Lang) => ({pt:"pt-IE",en:"en-IE",ru:"ru-RU",ro:"ro-RO"} as const)[lang];

export const DOW: Record<Lang, string[]> = {
  en: ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"],
  pt: ["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"],
  ru: ["Вс", "Пн", "Вт", "Ср", "Чт", "Пт", "Сб"],
  ro: ["Dum", "Lun", "Mar", "Mie", "Joi", "Vin", "Sâm"],
};

export const MONTHS: Record<Lang, string[]> = {
  en: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
  pt: ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"],
  ru: ["Янв", "Фев", "Мар", "Апр", "Май", "Июн", "Июл", "Авг", "Сен", "Окт", "Ноя", "Дек"],
  ro: ["Ian", "Feb", "Mar", "Apr", "Mai", "Iun", "Iul", "Aug", "Sep", "Oct", "Nov", "Dec"],
};

export const dayLabel = (lang: Lang, d: Date) => `${DOW[lang][d.getDay()]} ${d.getDate()} ${MONTHS[lang][d.getMonth()]}`;

/** "16 Jun – 30 Jun 2025" (ou o intervalo dado) */
export const rangeLabel = (lang: Lang, a: Date, b: Date) =>
  `${a.getDate()} ${MONTHS[lang][a.getMonth()]} – ${b.getDate()} ${MONTHS[lang][b.getMonth()]} ${b.getFullYear()}`;

export const periodLabel = (lang: Lang) => rangeLabel(lang, DAYS14[0]!, DAYS14[DAYS14.length - 1]!);
